-- 79_hauler_transport.sql -- map 751 Lordaeron extension, DB step 18.
--
-- GENERATED by Custom/Documentation/scripts/gen_map751_hauler_transport.py --
-- do not hand-edit; re-run the generator instead.
--
-- Makes the Horde Hauler (4144731) and Horde Coffin Hauler (4144764) work as the
-- rideable passenger wagons they are, rather than inert scenery.
--
-- WHY THEY ARE INERT: npcflag 16777216 is UNIT_NPC_FLAG_SPELLCLICK
-- (UnitDefines.h:346), NOT PLAYER_VEHICLE (0x02000000, :347). ObjectMgr.cpp:8633-8636
-- strips SPELLCLICK from any template carrying the flag with no npc_spellclick_spells
-- row -- and the import brought across ZERO spellclick rows for the whole
-- >=4,000,000 band, while cata_world has them. Flag stripped => no cursor, no 1015
-- opcode, no boarding. That is the single blocker; everything else here is content.
--
-- The player is a PASSENGER, not the driver: no seat of Vehicle 1048/1049 carries
-- VEHICLE_SEAT_FLAG_CAN_CONTROL (0x800).
--
-- Transposed from TrinityCore's own implementation:
--   src/server/scripts/EasternKingdoms/zone_silverpine_forest.cpp
--   sql/old/9.x/world/22082_2022_11_20/2022_10_01_01_world.sql
-- No coordinate transform is needed: TC node 5 (1376.23, 828.832, 48.75095) is
-- byte-identical to our spawn guid 16719448.

-- ---------------------------------------------------------------------------
-- 1. BLOCKER: the spell-click rows, without which the flag is stripped at boot
--
-- Cata uses spell 86807 'Ride Horde Hauler', which does not exist in this client
-- (verified against the live Spell.dbc, 53,799 records). We substitute 46598
-- 'Ride Vehicle Hardcoded' (VehicleDefines.h:52). That substitution is only valid
-- because BOTH entries have a real VehicleId -- HandleAuraControlVehicle bails on
-- !target->IsVehicle(), so 46598 on a non-vehicle is a silently dead click.
-- ---------------------------------------------------------------------------
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (4144731, 4144764);

INSERT INTO `npc_spellclick_spells` (`npc_entry`, `spell_id`, `cast_flags`, `user_type`) VALUES
(4144731, 46598, 1, 0),
(4144764, 46598, 1, 0);

-- ---------------------------------------------------------------------------
-- 2. The crew. TrinityCore's seat-2 row has accessory_entry = 0 (the player's
--    slot); ObjectMgr rejects a 0 accessory, and leaving seat 2 empty is exactly
--    where TC seats the player. Entries remapped +4100000.

--    NOTE: vehicle_template_accessory rows are only accepted for an entry that
--    already has a npc_spellclick_spells row, so section 1 must land first.
-- ---------------------------------------------------------------------------
