-- 5. Attach the route to the one real spawn.
--
--    MovementType 2 = WAYPOINT_MOTION_TYPE. Note the path is started by
--    Motion_Initialize (Creature.cpp:1114) BEFORE AI selection (:1116), so no AI
--    change is needed -- and do NOT set AIName='SmartAI' here, it would displace
--    VehicleAI (CreatureAISelector.cpp:63-65), which these already run.
-- ---------------------------------------------------------------------------
DELETE FROM `creature_addon` WHERE `guid` = 16716000;

