-- ---------------------------------------------------------------------------
-- 8. OPTIONAL / DESTRUCTIVE -- read before running.
--
-- Four of the five Horde Hauler 'spawns' are sniffer captures of the SAME moving
-- wagon, not spawn points. Proof: guid 16719448 (1376.23, 828.832, 48.7509) is
-- byte-identical to route node 5, and each of the four sits on the route facing
-- the direction of travel. Left in place you get five wagons where there should be
-- one, four of them parked and inert.
--
-- Skip this section if you would rather keep them as static scenery.
-- ---------------------------------------------------------------------------
-- DELETE FROM `creature` WHERE `guid` IN (16714741, 16715001, 16715487, 16719448);

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
SELECT 'spellclick rows (want 2)' AS what, COUNT(*) AS n FROM `npc_spellclick_spells` WHERE `npc_entry` IN (4144731, 4144764)
UNION ALL SELECT 'accessory rows (want 7)', COUNT(*) FROM `vehicle_template_accessory` WHERE `entry` = 4144731
UNION ALL SELECT 'seat addon rows (want 4)', COUNT(*) FROM `vehicle_seat_addon` WHERE `SeatEntry` IN (8394,8395,8396,8397)
UNION ALL SELECT 'waypoint nodes (want 63)', COUNT(*) FROM `waypoint_data` WHERE `id` = 447310
UNION ALL SELECT 'engineer texts (want 4)', COUNT(*) FROM `creature_text` WHERE `CreatureID` = 4144734
UNION ALL SELECT 'routed spawn (want 1)', COUNT(*) FROM `creature` c JOIN `creature_addon` a ON a.`guid` = c.`guid`
WHERE c.`guid` = 16716000 AND c.`MovementType` = 2 AND a.`path_id` = 447310;

-- must be empty: an accessory creature that does not exist
SELECT 'PROBLEM: missing accessory creature' AS problem, a.`accessory_entry`
FROM `vehicle_template_accessory` a
LEFT JOIN `creature_template` t ON t.`entry` = a.`accessory_entry`
WHERE a.`entry` = 4144731 AND t.`entry` IS NULL;

-- must be empty: a template still carrying SPELLCLICK with no row (flag gets stripped)
SELECT 'PROBLEM: SPELLCLICK with no spellclick row' AS problem, t.`entry`, t.`name`, t.`VehicleId`
FROM `creature_template` t
WHERE t.`entry` IN (4144731, 4144764) AND (t.`npcflag` & 16777216)
  AND NOT EXISTS (SELECT 1 FROM `npc_spellclick_spells` s WHERE s.`npc_entry` = t.`entry`);
